-- =========================================================
-- SMARTSTOCK AI - SEEDER (demo data)
-- Run AFTER schema.sql. Safe to run again: it clears the
-- demo tables first (settings are kept).
-- All dates are relative to CURDATE(), so the dashboard,
-- charts and AI predictions always look up to date.
-- Contents: 6 categories, 3 warehouses, 6 suppliers,
--           22 products, 348 orders (755 order lines)
-- =========================================================

USE smartstock;

-- Clear old demo data. DELETE (not TRUNCATE) in child -> parent order works
-- even when phpMyAdmin's "Enable foreign key checks" option is ticked.
DELETE FROM stock_movements;
DELETE FROM order_items;
DELETE FROM inventory;
DELETE FROM orders;
DELETE FROM products;
DELETE FROM suppliers;
DELETE FROM warehouses;
DELETE FROM categories;
DELETE FROM prediction_runs;
ALTER TABLE stock_movements AUTO_INCREMENT = 1;
ALTER TABLE order_items AUTO_INCREMENT = 1;
ALTER TABLE inventory AUTO_INCREMENT = 1;
ALTER TABLE orders AUTO_INCREMENT = 1;
ALTER TABLE products AUTO_INCREMENT = 1;
ALTER TABLE suppliers AUTO_INCREMENT = 1;
ALTER TABLE warehouses AUTO_INCREMENT = 1;
ALTER TABLE categories AUTO_INCREMENT = 1;
ALTER TABLE prediction_runs AUTO_INCREMENT = 1;

