-- 7. ORDER ITEMS

-- 8. POST ORDER STOCK MOVEMENTS (same rules as the app's sync engine)
--    purchase -> stock IN when Delivered
--    sale     -> stock OUT when In Transit or Delivered
SELECT oi.product_id,
       o.warehouse_id,
       o.id,
       CASE WHEN o.order_type = 'sale' THEN 'sale' ELSE 'purchase' END,
       CASE WHEN o.order_type = 'sale' THEN -SUM(oi.quantity) ELSE SUM(oi.quantity) END,
       CONCAT(CASE WHEN o.order_type = 'sale' THEN 'Sold via ' ELSE 'Received via ' END, o.order_no),
       (CASE WHEN o.order_type = 'purchase' THEN o.delivered_date
             ELSE COALESCE(o.delivered_date, o.order_date) END) + INTERVAL 12 HOUR
  FROM orders o
  JOIN order_items oi ON oi.order_id = o.id
 WHERE (o.order_type = 'purchase' AND o.status = 'Delivered')
    OR (o.order_type = 'sale' AND o.status IN ('In Transit', 'Delivered'))
 GROUP BY oi.product_id, o.warehouse_id, o.id, o.order_type, o.order_no, o.delivered_date, o.order_date;

UPDATE orders
   SET stock_applied = 1
 WHERE (order_type = 'purchase' AND status = 'Delivered')
    OR (order_type = 'sale' AND status IN ('In Transit', 'Delivered'));

-- 9. BUILD INVENTORY TOTALS FROM THE LEDGER
SELECT product_id, warehouse_id, SUM(quantity), NOW()
  FROM stock_movements
 GROUP BY product_id, warehouse_id;

-- 10. MARK SYNC TIME
ON DUPLICATE KEY UPDATE setting_value = VALUES(setting_value);
